import{_ as l,l as r,o as a,c as o,v as t,p as n,x as i,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"Feistel 与 DES 对照","description":"","frontmatter":{"title":"Feistel 与 DES 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/feistel-des.md","filePath":"cs/feistel-des.md","lastUpdated":1789023840000}'),c={name:"cs/feistel-des.md"};function p(S,e,D,f,A,u){const s=r("Mermaid");return a(),o("div",null,[e[1]||(e[1]=t('<h1 id="feistel-与-des-对照" tabindex="-1">Feistel 与 DES 对照 <a class="header-anchor" href="#feistel-与-des-对照" aria-label="Permalink to &quot;Feistel 与 DES 对照&quot;">​</a></h1><div class="epigraph"><p>Feistel 把块分成两半，一轮只用一边做轮函数再交叉；即使轮函数可逆性弱，整圈置换仍可逆。DES 是它的历史实例，块太小，今日不当新设计的默认。</p><footer>—— Feistel, Cryptography and Computer Privacy, Scientific American, 1973；NIST FIPS 46-3（历史）</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/aes-structure">AES</a>是代换–置换网络。缺口是<strong>另一族结构</strong>：Feistel，以及为何 DES 退出主干。<a href="/cs/dh-vs-rsa">DH 与 RSA 分工</a>不在这里重写；本课只对照块密码骨架。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AES 每圈都要 MixColumns 这类可逆线性层。Feistel：\\(R&#39;=L\\oplus F(R,k_i)\\)，\\(L&#39;=R\\)，解密即倒圈。DES：64 比特块、56 比特有效密钥，8 个 S 盒。缺口是结构对照与参数过时：生日界下 64 比特块在大量数据下碰撞；56 比特密钥可穷举。3DES 是权宜，不是目标。</p><h3 id="不教破解步骤" tabindex="-1">不教破解步骤 <a class="header-anchor" href="#不教破解步骤" aria-label="Permalink to &quot;不教破解步骤&quot;">​</a></h3><p>本课不给差分分析或穷举的操作序列。只需：块小、密钥短是规格失败，换 AES/ChaCha，不要「加奇异 S 盒」当创新。</p><p><span class="marginnote">Luby–Rackoff：足够独立的伪随机轮函数可把 Feistel 做成 PRP。DES 的实际轮函数不是理想对象；分析史说明余量不够今日。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画三圈 Feistel 的交叉。对照 AES：无需把 F 做成可逆。列出 DES 的参数缺陷。指出许多「类 DES」只换 S 盒仍继承 64 比特块。</p>',12)),(a(),n(h,null,{default:i(()=>[E(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%B7%A6%E5%8D%8A%22%5D%20--%3E%20XOR%5B%22%E2%8A%95%20F(%E5%8F%B3%E5%8D%8A%2C%20%E8%BD%AE%E5%AF%86%E9%92%A5)%22%5D%0A%20%20R%5B%22%E5%8F%B3%E5%8D%8A%22%5D%20--%3E%20F%5B%22%E8%BD%AE%E5%87%BD%E6%95%B0%20F%22%5D%0A%20%20F%20--%3E%20XOR%0A%20%20XOR%20--%3E%20R2%5B%22%E6%96%B0%E5%8F%B3%E5%8D%8A%22%5D%0A%20%20R%20--%3E%20L2%5B%22%E6%96%B0%E5%B7%A6%E5%8D%8A%20%3D%20%E6%97%A7%E5%8F%B3%E5%8D%8A%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Feistel 把可逆性从 F 上卸走，实现友好。安全仍取决于 F 的混乱与扩散以及圈数。DES 作为历史对照：能讲清「为何要换」，不能当新协议的分组密码。后课流密码 ChaCha 走另一条路：不分组，直接造 PRG 式的密钥流。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 3DES 的 EDE 细节写成推荐。不要在新系统里启用 DES。下一课 ChaCha20：ARX 软件流密码，对照 AES 的硬件友好 SPN。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AES 是 SPN；Feistel 用交叉使整圈可逆。</li><li>DES 块 64、密钥 56，规格上已退出默认。</li><li>Luby–Rackoff 说明理想轮函数下 Feistel 可成 PRP。</li><li>ChaCha20 是下一条软件向密钥流。</li><li>出处：Feistel, 1973；FIPS 46；Luby and Rackoff；对照 FIPS 197。</li></ul>',8))])}const m=l(c,[["render",p]]);export{F as __pageData,m as default};
